use super::*;
use semio_framework_test_fixtures::fixture_text;
#[test]
fn original_bytes_retirement_metadata_keeps_fixed_copy0_and_actual_physical_receipts(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../📦️bytes/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];assert_eq!(p["copyBytes"].as_u64().unwrap()as usize,size_of::<Vec<u8>>());let n=|k:&str|p[k].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for row in law["cases"].as_array().unwrap(){let text=row["text"].as_str().unwrap();let mut original=Vec::with_capacity(row["capacity"].as_u64().unwrap()as usize);original.extend_from_slice(text.as_bytes());let expected=original.capacity();let pointer=original.as_ptr();assert_eq!(serde_json::to_value(&original).unwrap(),serde_json::to_value(text.as_bytes()).unwrap());let mut owner=Bytes(ManuallyDrop::new(original),false);let mut total_release=0;
  for _ in 0..16{if owner.terminal_is_empty(){break}assert_eq!(owner.next_work_byte_demand().unwrap(),owner.next_demand(0).unwrap().copy_bytes);assert!(owner.next_work_byte_demand().unwrap()<=size_of::<Vec<u8>>());let release=owner.next_close_byte_demand().unwrap();let before=(owner.0.as_ptr(),owner.0.len(),owner.0.capacity());for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g},RetainedCloneGrant{maximum_release_bytes:release.saturating_sub(1),..g}]{if release==0&&denied.maximum_items>0&&denied.maximum_depth>0{continue}let(result,heap)=crate::retirement::effect_fixture::observed(denied,|effect|owner.close_step(effect));assert!(matches!(result,RetirementStep::BudgetExhausted));assert_eq!(heap,(0,0));assert_eq!((owner.0.as_ptr(),owner.0.len(),owner.0.capacity()),before)}
   let(step,heap)=crate::retirement::effect_fixture::observed(g,|effect|owner.close_step(effect));assert_eq!(heap.0,0);let RetirementStep::Progress(progress,work)=step else{panic!("native metadata retirement did not report progress")};assert_eq!(work,1);assert_eq!(heap.1,progress.released_bytes);assert!(progress.copied_bytes<=size_of::<Vec<u8>>(),"native metadata retirement invented payload copy");assert!(progress.fits(g));total_release+=progress.released_bytes;if owner.0.capacity()>0{assert_eq!(owner.0.as_ptr(),pointer)}}
  assert!(owner.terminal_is_empty());assert_eq!(total_release,expected);let(_,heap)=crate::allocation_testing::observe_retirement_allocations(||drop(owner));assert_eq!(heap,(0,0));
 }
}
